extra_head_css:
.tool-flex { display: flex; gap: 24px; flex-wrap: wrap; }
    .tool-sidebar { flex: 0 0 320px; display: flex; flex-direction: column; gap: 14px; }
    .tool-canvas-area { flex: 1; min-width: 300px; }
    @media (max-width: 768px) { .tool-flex { flex-direction: column; } .tool-sidebar { flex: none; width: 100%; } }

    .preview-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border:1px solid var(--border-color); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 350px; overflow: auto;
    }
    .preview-wrapper img, .preview-wrapper canvas { max-width: 100%; max-height: 65vh; border-radius: 4px; }

    .format-select { display: flex; gap: 6px; flex-wrap: wrap; }
    .format-btn {
      padding: 8px 16px; border: 1px solid var(--border-color); border-radius: 8px;
      background: var(--bg-primary); color: var(--text-secondary); cursor: pointer;
      font-size: .82rem; font-weight: 500; transition: all .2s;
    }
    .format-btn:hover { border-color: var(--accent); }
    .format-btn.active { border-color: var(--accent); background: rgba(99,102,241,.12); color: var(--accent); }

    .slider-group { display: flex; flex-direction: column; gap: 4px; margin-bottom: 12px; }
    .slider-group label { font-size: .78rem; color: var(--text-secondary); font-weight: 500; display: flex; justify-content: space-between; }
    .slider-group input[type="range"] { width: 100%; accent-color: var(--accent); }
    .slider-value { color: var(--accent); font-weight: 600; }

    .file-info { font-size: .78rem; color: var(--text-secondary); padding: 8px 12px; background: var(--bg-secondary); border-radius: 8px; line-height: 1.6; }

    .btn-group { display: flex; gap: 8px; flex-wrap: wrap; }
    .multi-download { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }
    .multi-download a { font-size: .8rem; color: var(--accent); text-decoration: none; padding: 6px 10px; background: rgba(99,102,241,.08); border-radius: 6px; display: flex; justify-content: space-between; }
    .multi-download a:hover { background: rgba(99,102,241,.15); }
